53	// Higiene de log (LGPD): redige o wstoken (e sesskey/token) de qualquer string
54	// que va para o log — mensagens de erro de fetch podem ecoar a URL do Moodle
55	// com o token. Usar em TODO console.* que possa conter URL/erro do Moodle.
56	function stripToken(value: unknown): string {
57	    const s = value instanceof Error ? (value.message || String(value)) : String(value ?? '');
58	    return s.replace(/(wstoken|sesskey|token)=[^&\s"']+/gi, '$1=REDACTED');
