78	// ── LLM com fallback + gate de qualidade ─────────────────────────────────────
79	// Tenta cada modelo da cascata. Uma resposta só é aceita se passar no gate
80	// (normalizeAnswer + isAcceptableAnswer); caso contrário, tenta o próximo
81	// modelo. Se NENHUMA passar mas alguma trouxe texto, devolve a melhor reserva
82	// (best-effort) — Darcy nunca fica mudo enquanto houver qualquer saída.
83	
84	async function callLLMDirect(apiKey: string, messages: any[]): Promise<LLMResult> {
85	    // chain = telemetria: registra TODA tentativa (modelo, status, desfecho,
86	    // latência, tokens) — é o que permite reordenar a cascata com dado real.
87	    const chain: ModelAttempt[] = [];
88	    let bestEffort: LLMResult | null = null;
89	
90	    for (const model of MODEL_IDS) {
91	        const ctrl = new AbortController();
92	        const timer = setTimeout(() => ctrl.abort(), LLM.TIMEOUT_MS);
93	        const t0 = Date.now();
94	        try {
95	            console.log(`[DARCY] Tentando: ${model}`);
96	            const res = await fetch('https://openrouter.ai/api/v1/chat/completions', {
97	                method: 'POST',
98	                signal: ctrl.signal,
99	                headers: {
100	                    'Authorization': `Bearer ${apiKey}`,
101	                    'Content-Type': 'application/json',
102	                    'HTTP-Referer': LLM.REFERER,
103	                    'X-Title': LLM.TITLE
104	                },
105	                body: JSON.stringify({ model, messages, temperature: LLM.TEMPERATURE, max_tokens: LLM.MAX_TOKENS, stream: false, usage: { include: true } })
106	            });
107	            const latency = Date.now() - t0;
108	            if (!res.ok) {
109	                console.warn(`[DARCY] ${model} -> ${res.status}`);
110	                chain.push({ model, status: res.status, outcome: 'http_error', latency_ms: latency });
111	                continue;
112	            }
113	            const data = await res.json();
114	            const usage = data.usage ?? null;
115	            const finishReason = data.choices?.[0]?.finish_reason ?? null;
116	            const content = normalizeAnswer(data.choices?.[0]?.message?.content);
117	            if (!content) {
118	                chain.push({ model, status: res.status, outcome: 'empty', latency_ms: latency, prompt_tokens: usage?.prompt_tokens, completion_tokens: usage?.completion_tokens });
119	                continue;
120	            }
121	            if (isAcceptableAnswer(content)) {
122	                console.log(`[DARCY] OK: ${model}`);
123	                chain.push({ model, status: res.status, outcome: 'ok', latency_ms: latency, prompt_tokens: usage?.prompt_tokens, completion_tokens: usage?.completion_tokens });
124	                return { content, model, chain, usage, gatePassed: true, wasBestEffort: false, finishReason };
125	            }
126	            // Tem texto mas reprovou no gate (recusa/idioma/eco): guarda como reserva.
127	            console.warn(`[DARCY] ${model} reprovou no gate de qualidade, tentando próximo`);
128	            chain.push({ model, status: res.status, outcome: 'gate_failed', latency_ms: latency, prompt_tokens: usage?.prompt_tokens, completion_tokens: usage?.completion_tokens });
129	            if (!bestEffort) bestEffort = { content, model, chain, usage, gatePassed: false, wasBestEffort: true, finishReason };
130	        } catch (e: any) {
131	            const reason = e?.name === 'AbortError' ? 'timeout' : (e?.message || 'erro');
132	            console.warn(`[DARCY] Erro ${model}: ${reason}`);
133	            chain.push({ model, status: null, outcome: 'exception', latency_ms: Date.now() - t0 });
134	        } finally {
135	            clearTimeout(timer);
136	        }
137	    }
138	
139	    if (bestEffort) {
140	        console.warn(`[DARCY] Nenhum modelo passou no gate; usando best-effort de ${bestEffort.model}`);
141	        return { ...bestEffort, chain }; // chain completa (todas as tentativas)
142	    }
143	    throw new Error('Todos os modelos falharam');
144	}
