146	// ── Mini agent loop (in-course: tool calling em até 2 iterações) ─────────────
147	
148	type AgentResult = LLMResult & { toolCalls: any[]; agentIterations: number };
149	
150	// Soma usage entre chamadas (pagamos por TODAS as iterações + tool calls).
151	function mergeUsage(a: any, b: any): any {
152	    if (!a) return b ? { ...b } : null;
153	    if (!b) return a;
154	    return {
155	        prompt_tokens: (a.prompt_tokens || 0) + (b.prompt_tokens || 0),
156	        completion_tokens: (a.completion_tokens || 0) + (b.completion_tokens || 0),
157	        total_tokens: (a.total_tokens || 0) + (b.total_tokens || 0),
158	        cost: (a.cost || 0) + (b.cost || 0),
159	    };
160	}
