162	async function agentLoop(
163	    apiKey: string,
164	    messages: any[],
165	    tools: any[],
166	    moodleBase: string,
167	    moodleToken: string,
168	    supabase: any | null,
169	    context: any
170	): Promise<AgentResult> {
171	    let usedModel = PRIMARY_MODEL;
172	    const MAX_ITER = 2;
173	    // Telemetria agregada do loop agêntico
174	    const chain: ModelAttempt[] = [];
175	    const toolCallsLog: any[] = [];
176	    let aggUsage: any = null;
177	    let lastFinish: string | null = null;
178	
179	    for (let iter = 0; iter < MAX_ITER; iter++) {
180	        // Na última iteração remove tools para forçar resposta de texto
181	        const activeTools = iter < MAX_ITER - 1 ? tools : [];
182	
183	        console.log(`[AGENT] Iteracao ${iter + 1}/${MAX_ITER} (${activeTools.length} tools)`);
184	        let tCall = Date.now();
185	        let result = await callOpenRouterWithTools(apiKey, messages, activeTools, usedModel, 'auto');
186	        chain.push({ model: usedModel, status: result.error ? null : 200, outcome: result.error ? 'http_error' : 'ok', latency_ms: Date.now() - tCall, prompt_tokens: result.usage?.prompt_tokens, completion_tokens: result.usage?.completion_tokens });
187	        if (!result.error) { aggUsage = mergeUsage(aggUsage, result.usage); lastFinish = result.finish_reason ?? lastFinish; }
188	
189	        // Fallback de modelo se falhar
190	        if (result.error) {
191	            for (const fallback of FALLBACK_MODELS) {
192	                console.warn(`[AGENT] Fallback para ${fallback}`);
193	                tCall = Date.now();
194	                result = await callOpenRouterWithTools(apiKey, messages, activeTools, fallback, 'auto');
195	                chain.push({ model: fallback, status: result.error ? null : 200, outcome: result.error ? 'http_error' : 'ok', latency_ms: Date.now() - tCall, prompt_tokens: result.usage?.prompt_tokens, completion_tokens: result.usage?.completion_tokens });
196	                if (!result.error) { usedModel = fallback; aggUsage = mergeUsage(aggUsage, result.usage); lastFinish = result.finish_reason ?? lastFinish; break; }
197	            }
198	        }
199	
200	        if (result.error || !result) {
201	            return { content: 'Nao consegui processar sua solicitacao no momento. Tente novamente.', model: usedModel, chain, usage: aggUsage, gatePassed: false, wasBestEffort: true, finishReason: lastFinish, toolCalls: toolCallsLog, agentIterations: iter + 1 };
202	        }
203	
204	        // Sem tool calls: resposta final
205	        if (!result.tool_calls || result.tool_calls.length === 0) {
206	            const content = (result.content || '').trim();
207	            if (content) return { content, model: usedModel, chain, usage: aggUsage, gatePassed: true, wasBestEffort: false, finishReason: lastFinish, toolCalls: toolCallsLog, agentIterations: iter + 1 };
208	            // conteúdo vazio — força próxima iteração sem tools
209	            continue;
210	        }
211	
212	        // Executa tools em paralelo
213	        console.log(`[AGENT] ${result.tool_calls.length} tool(s) chamada(s)`);
214	        messages = [
215	            ...messages,
216	            { role: 'assistant', content: result.content || null, tool_calls: result.tool_calls }
217	        ];
218	
219	        const toolResults = await Promise.all(
220	            result.tool_calls.map(async (tc: any) => {
221	                // Free models às vezes emitem argumentos malformados — não deixe
222	                // um JSON inválido derrubar a request inteira; devolve erro ao modelo.
223	                let args: any = {};
224	                try {
225	                    args = JSON.parse(tc.function?.arguments || '{}');
226	                } catch (_e) {
227	                    toolCallsLog.push({ name: tc.function?.name || 'unknown', ok: false });
228	                    return { role: 'tool', tool_call_id: tc.id, content: JSON.stringify({ error: 'argumentos inválidos (JSON malformado)' }) };
229	                }
230	                const toolResult = await executeTool(
231	                    tc.function.name,
232	                    args,
233	                    moodleBase,
234	                    moodleToken,
235	                    supabase,
236	                    context
237	                );
238	                toolCallsLog.push({ name: tc.function?.name || 'unknown', ok: true });
239	                return { role: 'tool', tool_call_id: tc.id, content: JSON.stringify(toolResult) };
240	            })
241	        );
242	
243	        messages = [...messages, ...toolResults];
244	    }
245	
246	    // Se chegou aqui sem resposta, faz chamada direta sem tools
247	    const final = await callLLMDirect(apiKey, messages);
248	    return { ...final, chain: [...chain, ...final.chain], usage: mergeUsage(aggUsage, final.usage), toolCalls: toolCallsLog, agentIterations: MAX_ITER };
249	}
