// Vozes xAI Realtime:
// - eve: feminina, energética
// - ara: feminina, acolhedora
// - rex: MASCULINA, confiante e clara (padrão do Darcy — educador sênior)
// - leo: MASCULINA, autoritária e forte (alternativa — mais comando)
// - sal: neutra, equilibrada
// Darcy usa "rex" por padrão — voz masculina madura, adequada à figura de
// Darcy Ribeiro (humanista, educador acolhedor).
type VoiceId = "eve" | "ara" | "rex" | "sal" | "leo";
const VALID_VOICES: Set<string> = new Set(["eve", "ara", "rex", "sal", "leo"]);
const DEFAULT_VOICE: VoiceId = "rex";

function sanitizeVoice(v: unknown): VoiceId {
    if (typeof v === "string") {
        const lower = v.toLowerCase();
        if (VALID_VOICES.has(lower)) return lower as VoiceId;
    }
    return DEFAULT_VOICE;
}

// ─── Prefetch Moodle (paridade com darcy-chat) ─────────────────────────────
// US-009: a voz usa a MESMA camada de dados do texto (../_shared/moodle.ts):
// resolveMoodleInstance, fetchMoodleUser (perfil + cursos), fetchFullCourseContext
// (conteúdo do curso) e verifyMoodleRole (papel server-side). O bloco de perfil/
// cursos é renderizado por getAcademicContextString (idêntico ao texto); só o
// CURSO atual ganha um formatter compacto de voz (formatCourseDataForVoice) pra
// não estourar o limite de tokens das instructions realtime.
//
// resolveMoodleInstance vem do _shared (removida a cópia inline). moodleUrl
// permanece aqui porque ainda é usada pelas tools realtime inline (US-010).

function moodleUrl(base: string, token: string, fn: string, params: Record<string, string> = {}): string {
    const u = new URL(`${base}/webservice/rest/server.php`);
    u.searchParams.set("wstoken", token);
    u.searchParams.set("moodlewsrestformat", "json");
    u.searchParams.set("wsfunction", fn);
    for (const [k, v] of Object.entries(params)) u.searchParams.set(k, v);
    return u.toString();
}

// ─── Moodle activity type labels (pt-BR) ─────────────────────────────────────
const ACTIVITY_TYPE_LABELS: Record<string, string> = {
    assign: "Tarefas",
    quiz: "Questionários",
    forum: "Fóruns",
    resource: "Arquivos",
    page: "Páginas",
    url: "Links",
    folder: "Pastas",
    label: "Rótulos",
    book: "Livros",
    lesson: "Lições",
    workshop: "Workshops",
    h5pactivity: "H5P",
    scorm: "SCORM",
    bigbluebuttonbn: "Videoconferências",
    choice: "Enquetes",
    glossary: "Glossários",
    wiki: "Wikis",
    feedback: "Feedbacks",
    chat: "Chats",
};

// Formatter COMPACTO de voz a partir do FullCourseContext compartilhado.
// US-009: os DADOS vêm de fetchFullCourseContext (../_shared/moodle.ts) — aqui só
// adaptamos a SAÍDA pro frame de voz (agrupado por tipo, IDs de fórum pra tool,
// notas resumidas) sem reimplementar nenhuma busca. formatCourseContextForPrompt
// do texto é verboso demais (até 25KB) pro limite de tokens das instructions
// realtime, então mantemos esta versão enxuta.
function formatCourseDataForVoice(ctx: FullCourseContext, courseName: string): string {
    const hasAny = ctx.sections.length || ctx.forums.length || ctx.grades.length;
    if (!hasAny) return "";

    let out = `\n### Dados do curso "${courseName}" (use para responder sobre atividades, fóruns, notas, prazos):\n`;

    // Atividades: achata os módulos das seções e agrupa por tipo (modname).
    // Prazos vêm de assignments[].duedate / quizzes[].timeclose (o FullCourseContext
    // já normaliza essas datas), casados por nome com os módulos correspondentes.
    interface ActSummary { name: string; due?: string }
    const byType: Record<string, ActSummary[]> = {};
    const dueByName: Record<string, string> = {};
    for (const a of ctx.assignments) {
        if (a.name && a.duedate && a.duedate > 0) {
            try { dueByName[a.name.toLowerCase()] = new Date(a.duedate * 1000).toLocaleDateString("pt-BR"); } catch { /* ignore */ }
        }
    }
    for (const q of ctx.quizzes) {
        if (q.name && q.timeclose && q.timeclose > 0) {
            try { dueByName[q.name.toLowerCase()] = new Date(q.timeclose * 1000).toLocaleDateString("pt-BR"); } catch { /* ignore */ }
        }
    }
    let totalActivities = 0;
    for (const section of ctx.sections) {
        for (const mod of section.modules) {
            const name = (mod.name || "").trim();
            if (!name) continue;
            const type = (mod.modname || "").trim();
            totalActivities++;
            (byType[type] = byType[type] || []).push({ name, due: dueByName[name.toLowerCase()] });
        }
    }

    if (totalActivities > 0) {
        out += `Atividades do curso (${totalActivities} total):\n`;
        // Prioriza tipos com prazo / avaliativos
        const priorityOrder = ["assign", "quiz", "workshop", "lesson", "forum", "h5pactivity", "scorm", "choice", "resource", "page", "url", "folder", "book"];
        for (const type of priorityOrder) {
            if (!byType[type]) continue;
            const label = ACTIVITY_TYPE_LABELS[type] || type;
            const items = byType[type];
            out += `- ${label} (${items.length}): `;
            const preview = items.slice(0, 6).map((a) => `${a.name}${a.due ? ` [prazo ${a.due}]` : ""}`);
            out += preview.join("; ");
            if (items.length > 6) out += `; ...+${items.length - 6}`;
            out += "\n";
        }
        // Tipos fora da priority
        for (const [type, items] of Object.entries(byType)) {
            if (priorityOrder.includes(type)) continue;
            const label = ACTIVITY_TYPE_LABELS[type] || type;
            out += `- ${label} (${items.length}): `;
            out += items.slice(0, 4).map((a) => a.name).join("; ");
            if (items.length > 4) out += `; ...+${items.length - 4}`;
            out += "\n";
        }
    }

    // Fóruns (IDs são úteis para a tool read_forum_discussions)
    if (ctx.forums.length > 0) {
        out += `Fóruns disponíveis:\n`;
        for (const f of ctx.forums.slice(0, 8)) {
            out += `- "${f.name}" (forum_id=${f.id})\n`;
        }
        if (ctx.forums.length > 8) out += `- ...+${ctx.forums.length - 8} fóruns\n`;
    }

    // Notas do aluno neste curso
    if (ctx.grades.length > 0) {
        out += `Notas do aluno neste curso:\n`;
        const withGrade = ctx.grades.filter((g) => g.gradeformatted || g.graderaw !== undefined);
        const withoutGrade = ctx.grades.filter((g) => !g.gradeformatted && g.graderaw === undefined);
        for (const g of withGrade.slice(0, 12)) {
            const val = g.gradeformatted ?? String(g.graderaw);
            out += `- ${g.itemname}: ${val}`;
            if (g.feedback) out += ` [feedback: ${g.feedback}]`;
            out += "\n";
        }
        if (withoutGrade.length > 0) {
            out += `- Ainda sem nota lançada (${withoutGrade.length}): `;
            out += withoutGrade.slice(0, 5).map((g) => g.itemname).join("; ");
            if (withoutGrade.length > 5) out += `; ...+${withoutGrade.length - 5}`;
            out += "\n";
        }
    }

    return out;
}

// Nomes dos módulos do curso (ancoram update_student_mastery) — mesma lógica do texto.
function extractCourseModuleNames(sections: FullCourseContext["sections"]): string[] {
    const names: string[] = [];
    for (const section of sections || []) {
        for (const mod of section.modules || []) {
            if (mod.name && mod.modname !== "label") {
                names.push(mod.name.trim());
            }
        }
    }
    return names;
}

// Prefetch acadêmico da voz — agora 100% sobre a camada compartilhada.
// Retorna { academicContext, role, courseModules } pra que a sessão use o papel
// SERVER-SIDE (verifyMoodleRole) e não apenas o que o cliente enviou, e pra que o
// adapter realtime ancore update_student_mastery nos módulos do curso (como o texto).
async function fetchAcademicContext(
    ctx: Record<string, unknown>,
    supabase: any,
): Promise<{ academicContext: string; role: UserRole; courseModules: string[] }> {
    const moodleUserId = typeof ctx.moodleUserId === "string" || typeof ctx.moodleUserId === "number"
        ? String(ctx.moodleUserId)
        : null;
    if (!moodleUserId || !/^\d+$/.test(moodleUserId)) return { academicContext: "", role: "guest", courseModules: [] };

    const { base, token } = resolveMoodleInstance(typeof ctx.url === "string" ? ctx.url : undefined);
    if (!token) {
        console.warn("[darcy-voice] Sem token Moodle para", base);
        return { academicContext: "", role: "guest", courseModules: [] };
    }

    const currentCourseId = typeof ctx.courseId === "string" || typeof ctx.courseId === "number"
        ? String(ctx.courseId).trim()
        : "";
    const hasCourse = !!(currentCourseId && /^\d+$/.test(currentCourseId) && currentCourseId !== "0");
    const courseName = typeof ctx.courseName === "string" ? ctx.courseName : "";

    try {
        // SECURITY: papel verificado no servidor (como o texto faz). Sem confiar no
        // userRole do cliente. Só verifica quando temos user+curso+token.
        let role: UserRole = "student";
        const rolePromise: Promise<UserRole> = hasCourse
            ? verifyMoodleRole(base, token, moodleUserId, currentCourseId)
            : Promise.resolve("student");

        // perfil + cursos (getAcademicContextString) e conteúdo do curso atual
        // — MESMAS funções do texto (../_shared/moodle.ts).
        const [moodleUser, fullCourseCtx, verifiedRole] = await Promise.all([
            fetchMoodleUser(base, token, moodleUserId, hasCourse ? currentCourseId : null),
            hasCourse
                ? fetchFullCourseContext(base, token, Number(currentCourseId), Number(moodleUserId)).catch(() => null)
                : Promise.resolve(null),
            rolePromise,
        ]);
        role = verifiedRole;
        console.log(`[darcy-voice] Role verified: server=${role} (curso=${hasCourse ? currentCourseId : "—"})`);

        // Bloco perfil/cursos: formatter IDÊNTICO ao texto (getAcademicContextString).
        let out = (moodleUser.userData || moodleUser.coursesData)
            ? getAcademicContextString(
                moodleUser.userData,
                moodleUser.coursesData,
                role,
                undefined,
                hasCourse ? currentCourseId : null,
            )
            : "";

        // Bloco do curso atual: formatter COMPACTO de voz sobre o FullCourseContext.
        if (fullCourseCtx) {
            out += formatCourseDataForVoice(fullCourseCtx, courseName || `ID ${currentCourseId}`);
        }

        // learningProfile (mastery do Supabase) — só aluno dentro de curso, como o texto.
        if (supabase && hasCourse && role === "student") {
            const learningProfile = await getStudentLearningProfile(supabase, moodleUserId, currentCourseId);
            if (learningProfile) {
                out += "\n" + learningProfile;
                console.log("[darcy-voice] Learning profile carregado");
            }
        }

        // Módulos do curso pra ancorar update_student_mastery (igual ao texto).
        const courseModules = fullCourseCtx ? extractCourseModuleNames(fullCourseCtx.sections) : [];

        return { academicContext: out, role, courseModules };
    } catch (err) {
        console.error("[darcy-voice] prefetch Moodle falhou:", err);
        return { academicContext: "", role: "student", courseModules: [] };
    }
}

// ─── Tools realtime (function calling via xAI Realtime) ──────────────────
// Permitem consulta DINÂMICA ao Moodle durante a conversa (não só snapshot inicial).
// xAI Realtime segue schema OpenAI: session.update traz tools; o modelo emite
// response.function_call_arguments.done; nós executamos e devolvemos via
// conversation.item.create (function_call_output) + response.create.

// US-010: o estado Moodle da sessão carrega agora o CONTEXTO resolvido (com o papel
// server-side) e o client Supabase, para alimentar tanto o adapter realtime
// (toRealtimeTools — gating) quanto o executor compartilhado (executeTool — guards).
interface MoodleContextState {
    base: string;
    token: string;
    userId: string;
    courseId?: string;        // presente quando dentro de um curso específico
    // deno-lint-ignore no-explicit-any
    context: any;             // contexto resolvido (userId, courseId, userRole/Ids) — base de gating/guards
    // deno-lint-ignore no-explicit-any
    supabase: any | null;     // service_role para mastery/perfil (tools de escrita)
    courseModules: string[];  // nomes de módulos do curso (embutidos em update_student_mastery)
}

// ── Tools realtime: registry COMPARTILHADO + complemento voice-only ──────────
// US-010: a voz expõe o registry completo (toRealtimeTools, com o MESMO gating do
// texto) e executa pelo executeTool compartilhado (guards). As tools abaixo são
// VOICE-ONLY (não existem no registry de texto): retornam STRING compacta otimizada
// pra fala. São de leitura e gated por presença de sessão/curso, como antes.
// `read_forum_discussions` (alias falado) coexiste com o `mod_forum_get_forum_discussions`
// do registry; o roteamento por REGISTRY_TOOL_NAMES garante que cada uma vá ao
// executor certo.
function buildVoiceOnlyToolDefs(state: MoodleContextState): Array<Record<string, unknown>> {
    const tools: Array<Record<string, unknown>> = [
        {
            type: "function",
            name: "list_all_my_courses",
            description: "Lista TODOS os cursos em que o usuário está matriculado. Use APENAS quando o contexto diz \"... e mais N cursos\" e o usuário pede a lista completa. Se o contexto já mostra tudo, NÃO CHAME.",
            parameters: { type: "object", properties: {}, required: [] },
        },
        {
            type: "function",
            name: "search_my_courses",
            description: "Busca nos cursos matriculados pelo nome (case-insensitive). Use quando perguntarem 'tenho curso de X?' e você NÃO vê o termo no contexto.",
            parameters: {
                type: "object",
                properties: { query: { type: "string", description: "Trecho do nome do curso. Mínimo 2 caracteres." } },
                required: ["query"],
            },
        },
        {
            type: "function",
            name: "refresh_user_profile",
            description: "Re-busca o perfil do usuário no Moodle agora. Use só se o aluno mudou algo e quer confirmar.",
            parameters: { type: "object", properties: {}, required: [] },
        },
    ];

    // Tools adicionais quando dentro de curso (Darcy Tutor)
    if (state.courseId) {
        tools.push(
            {
                type: "function",
                name: "read_forum_discussions",
                description: "Lê as DISCUSSÕES RECENTES de um fórum do curso atual. Use quando o aluno perguntar 'o que tá rolando no fórum X?', 'quais os últimos tópicos do fórum Y?', ou quiser resumo de discussões. O forum_id está disponível no contexto de curso (formato 'forum_id=NÚMERO').",
                parameters: {
                    type: "object",
                    properties: {
                        forum_id: { type: "number", description: "ID numérico do fórum (visível no contexto do curso)." },
                    },
                    required: ["forum_id"],
                },
            },
            {
                type: "function",
                name: "refresh_my_grades",
                description: "Re-busca as NOTAS ATUALIZADAS do aluno no curso atual. Use se o aluno disser 'minhas notas atualizaram?', 'tirou nota da prova?', ou se o contexto parecer desatualizado. Retorna cada item avaliativo com nota e feedback se houver.",
                parameters: { type: "object", properties: {}, required: [] },
            },
            {
                type: "function",
                name: "list_activities_by_type",
                description: "Filtra as atividades do curso atual por TIPO. Use quando o aluno perguntar 'quais tarefas tenho?', 'quais questionários?', 'quantos fóruns têm nesse curso?'. Tipos válidos: assign (tarefas), quiz (questionários), forum (fóruns), workshop (workshops), lesson (lições), resource (arquivos), page (páginas), url (links), folder (pastas), h5pactivity (H5P), scorm, choice (enquetes), glossary, wiki, feedback, bigbluebuttonbn (videoconferências), chat, book (livros).",
                parameters: {
                    type: "object",
                    properties: {
                        activity_type: { type: "string", description: "Tipo Moodle da atividade (ex: assign, quiz, forum)." },
                    },
                    required: ["activity_type"],
                },
            },
        );
    }

    return tools;
}

// Defs realtime completas da sessão: registry compartilhado (flat, gated por
// role/curso) + complemento voice-only.
//
// US-018 — GATING POR LOGIN (correção determinística da RESPOSTA DUPLA do anônimo):
// TODAS as tools desta sessão dependem de dados do usuário Moodle (cursos, notas,
// perfil, fóruns, arquivos, mastery). Logo, só são oferecidas quando há um
// moodleUserId REAL (número válido > 0). Sem login (anônimo), a lista fica VAZIA
// -> tool_choice='none' (ver session.update). Assim o modelo NÃO tenta buscar
// cursos de quem não tem login: ele responde UMA vez pela própria FAQ (orientando
// a logar / abrir "Meus Cursos") e não dispara a 2a response da tool que falava
// tudo de novo. moodleState só é montado no darcy.init quando o token Moodle
// resolveu (exige moodleUserId válido), então !state já cobre o anônimo; o guard
// de userId abaixo torna a regra explícita e robusta a futuras mudanças.
function isRealMoodleUserId(userId: unknown): boolean {
    const s = typeof userId === "string" || typeof userId === "number" ? String(userId).trim() : "";
    return /^\d+$/.test(s) && Number(s) > 0;
}
function buildVoiceToolDefs(state: MoodleContextState | null): Array<Record<string, unknown>> {
    // Sem sessão Moodle OU sem usuário logado real -> NENHUMA tool de dados.
    if (!state || !isRealMoodleUserId(state.userId)) return [];
    const hasSupabase = !!state.supabase;
    const shared = toRealtimeTools(hasSupabase, state.context, state.courseModules);
    const voiceOnly = buildVoiceOnlyToolDefs(state);
    return [...shared, ...voiceOnly];
}

// Executor VOICE-ONLY: só as tools de leitura específicas de voz (string compacta).
// As tools do registry compartilhado vão pelo executeTool de ../_shared/tools.ts.
async function executeVoiceOnlyTool(
    name: string,
    args: Record<string, unknown>,
    mctx: MoodleContextState | null,
): Promise<string> {
    if (!mctx) return "Moodle não disponível nesta sessão.";

    try {
        switch (name) {
            case "list_all_my_courses": {
                const r = await fetch(moodleUrl(mctx.base, mctx.token, "core_enrol_get_users_courses", { userid: mctx.userId }));
                if (!r.ok) return `Erro HTTP ${r.status} ao listar cursos.`;
                const courses = await r.json();
                if (!Array.isArray(courses)) return "Moodle não retornou lista de cursos.";
                if (courses.length === 0) return "Você não tem cursos matriculados.";
                const TEACHER_IDS = [1, 2, 3, 4];
                const lines = courses.map((c: Record<string, unknown>) => {
                    let roleLabel = "";
                    const roles = c.roles as Array<{ roleid?: number }> | undefined;
                    if (Array.isArray(roles) && roles.length > 0) {
                        const isTeacher = roles.some((r) => TEACHER_IDS.includes(Number(r?.roleid)));
                        roleLabel = ` [${isTeacher ? "Professor" : "Aluno"}]`;
                    }
                    return `${c.fullname} (ID: ${c.id})${roleLabel}`;
                });
                return `Total: ${courses.length} cursos.\n${lines.join("\n")}`;
            }

            case "search_my_courses": {
                const query = typeof args.query === "string" ? args.query.trim().toLowerCase() : "";
                if (query.length < 2) return "Query muito curta.";
                const r = await fetch(moodleUrl(mctx.base, mctx.token, "core_enrol_get_users_courses", { userid: mctx.userId }));
                if (!r.ok) return `Erro HTTP ${r.status} ao buscar cursos.`;
                const courses = await r.json();
                if (!Array.isArray(courses)) return "Moodle não retornou cursos.";
                const matches = courses.filter((c: Record<string, unknown>) => {
                    const name = String(c.fullname || "").toLowerCase();
                    const short = String(c.shortname || "").toLowerCase();
                    return name.includes(query) || short.includes(query);
                });
                if (matches.length === 0) return `Nenhum curso matriculado contém "${args.query}".`;
                const lines = matches.slice(0, 8).map((c: Record<string, unknown>) => `${c.fullname} (ID: ${c.id})`);
                return `Encontrados ${matches.length} curso(s):\n${lines.join("\n")}`;
            }

            case "refresh_user_profile": {
                const r = await fetch(moodleUrl(mctx.base, mctx.token, "core_user_get_users", {
                    "criteria[0][key]": "id",
                    "criteria[0][value]": mctx.userId,
                }));
                if (!r.ok) return `Erro HTTP ${r.status} ao buscar perfil.`;
                const data = await r.json();
                const user = Array.isArray(data?.users) ? data.users[0]
                    : Array.isArray(data) ? data[0] : null;
                if (!user) return "Perfil não encontrado.";
                const fullName = String(user.fullname || "").trim()
                    || `${String(user.firstname || "")} ${String(user.lastname || "")}`.trim();
                const out: string[] = [];
                if (fullName) out.push(`Nome: ${fullName}`);
                if (user.email) out.push(`E-mail: ${user.email}`);
                if (user.idnumber) out.push(`Matrícula/CPF: ${user.idnumber}`);
                if (user.city) out.push(`Cidade: ${user.city}`);
                if (user.institution) out.push(`Instituição: ${user.institution}`);
                if (user.department) out.push(`Departamento: ${user.department}`);
                return out.length ? out.join("; ") : "Perfil sem dados visíveis.";
            }

            case "read_forum_discussions": {
                if (!mctx.courseId) return "Esta ferramenta só funciona dentro de um curso.";
                const forumId = Number(args.forum_id);
                if (!forumId || !Number.isFinite(forumId)) return "ID do fórum inválido.";
                const url = new URL(`${mctx.base}/webservice/rest/server.php`);
                url.searchParams.set("wstoken", mctx.token);
                url.searchParams.set("moodlewsrestformat", "json");
                url.searchParams.set("wsfunction", "mod_forum_get_forum_discussions");
                url.searchParams.set("forumid", String(forumId));
                url.searchParams.set("page", "0");
                url.searchParams.set("perpage", "5");
                const r = await fetch(url.toString());
                if (!r.ok) return `Erro HTTP ${r.status} ao ler fórum.`;
                const data = await r.json();
                const discussions = Array.isArray(data?.discussions) ? data.discussions
                    : Array.isArray(data) ? data : [];
                if (discussions.length === 0) return `Fórum sem discussões ainda.`;
                const items = discussions.slice(0, 5).map((d: Record<string, unknown>) => {
                    const subject = String(d.subject || "(sem título)").trim();
                    const author = String(d.userfullname || d.author || "Desconhecido").trim();
                    const message = d.message
                        ? String(d.message).replace(/<[^>]*>/g, " ").replace(/\s+/g, " ").trim().slice(0, 180)
                        : "";
                    const replies = Number(d.numreplies ?? 0);
                    const date = d.created
                        ? new Date(Number(d.created) * 1000).toLocaleDateString("pt-BR")
                        : "";
                    return `"${subject}" por ${author}${date ? ` (${date})` : ""}${replies ? `, ${replies} respostas` : ""}: ${message}`;
                });
                return `Últimos ${items.length} tópicos:\n${items.join("\n")}`;
            }

            case "refresh_my_grades": {
                if (!mctx.courseId) return "Esta ferramenta só funciona dentro de um curso.";
                const r = await fetch(moodleUrl(mctx.base, mctx.token, "gradereport_user_get_grade_items", {
                    courseid: mctx.courseId,
                    userid: mctx.userId,
                }));
                if (!r.ok) return `Erro HTTP ${r.status} ao buscar notas.`;
                const data = await r.json();
                // deno-lint-ignore no-explicit-any
                const gradeItems = (data as any)?.usergrades?.[0]?.gradeitems;
                if (!Array.isArray(gradeItems) || gradeItems.length === 0) return "Nenhuma nota disponível ainda.";
                const out: string[] = [];
                for (const item of gradeItems.slice(0, 15) as Array<Record<string, unknown>>) {
                    const name = String(item.itemname || "").trim();
                    if (!name) continue;
                    const raw = item.gradeformatted ?? item.graderaw;
                    const grade = raw !== null && raw !== undefined && String(raw) !== "-" ? String(raw) : "(sem nota)";
                    out.push(`${name}: ${grade}`);
                }
                return out.length ? `Notas atuais:\n${out.join("\n")}` : "Ainda nenhuma nota lançada.";
            }

            case "list_activities_by_type": {
                if (!mctx.courseId) return "Esta ferramenta só funciona dentro de um curso.";
                const type = typeof args.activity_type === "string" ? args.activity_type.trim().toLowerCase() : "";
                if (!type) return "Tipo de atividade inválido.";
                const r = await fetch(moodleUrl(mctx.base, mctx.token, "core_course_get_contents", {
                    courseid: mctx.courseId,
                }));
                if (!r.ok) return `Erro HTTP ${r.status} ao listar atividades.`;
                const sections = await r.json();
                if (!Array.isArray(sections)) return "Resposta inválida do Moodle.";
                const filtered: Array<{ name: string; due?: string }> = [];
                for (const section of sections as Array<Record<string, unknown>>) {
                    const modules = section.modules as Array<Record<string, unknown>> | undefined;
                    if (!Array.isArray(modules)) continue;
                    for (const mod of modules) {
                        if (String(mod.modname) !== type) continue;
                        const name = String(mod.name || "").trim();
                        if (!name) continue;
                        let due: string | undefined;
                        const dates = mod.dates as Array<{ label?: string; timestamp?: number }> | undefined;
                        if (Array.isArray(dates)) {
                            const d = dates.find((x) => {
                                const l = String(x?.label || "").toLowerCase();
                                return l.includes("prazo") || l.includes("due") || l.includes("fecha");
                            });
                            if (d?.timestamp) {
                                try { due = new Date(Number(d.timestamp) * 1000).toLocaleDateString("pt-BR"); }
                                catch { /* ignore */ }
                            }
                        }
                        filtered.push({ name, due });
                    }
                }
                if (filtered.length === 0) {
                    const label = ACTIVITY_TYPE_LABELS[type] || type;
                    return `Nenhuma atividade do tipo "${label}" neste curso.`;
                }
                const label = ACTIVITY_TYPE_LABELS[type] || type;
                const items = filtered.slice(0, 10).map((a) => `${a.name}${a.due ? ` [prazo ${a.due}]` : ""}`);
                let msg = `${label} deste curso (${filtered.length} total):\n${items.join("\n")}`;
                if (filtered.length > 10) msg += `\n...+${filtered.length - 10}`;
                return msg;
            }
        }
    } catch (err) {
        console.error(`[darcy-voice] tool ${name} error`, err);
        return `Erro ao executar ${name}: ${err instanceof Error ? err.message : String(err)}`;
    }

    return `Tool desconhecida: ${name}`;
}

// ─── Semeadura do histórico texto→voz (US-016) ───────────────────────────────
// O cliente envia no darcy.init um campo `history` = últimas ~10 trocas da
// conversa de texto ([{role:'user'|'assistant', content:string}]). Para a IA de
// voz CONTINUAR o mesmo fio, pré-populamos a sessão xAI com esses turnos como
// `conversation.item.create` (MESMO mecanismo que sendToolOutputToUpstream usa
// pra function_call_output). NÃO disparamos response.create — só queremos popular
// o contexto; a IA responde quando o usuário falar.
const MAX_HISTORY_TURNS = 10;     // só os turnos mais recentes (evita estourar tokens da sessão)
const MAX_HISTORY_TEXT = 1000;    // trunca cada conteúdo (a sessão de voz tem orçamento de tokens enxuto)

// Constrói os eventos conversation.item.create a partir do history do cliente.
// Sanitiza: ignora roles != user/assistant e content vazio; trunca; limita a
// MAX_HISTORY_TURNS (mantendo os MAIS RECENTES). Formato xAI/OpenAI Realtime:
// user -> content[{type:'input_text'}], assistant -> content[{type:'text'}].
function buildHistorySeedItems(history: unknown): string[] {
    if (!Array.isArray(history) || history.length === 0) return [];
    const items: string[] = [];
    // Pega os últimos MAX_HISTORY_TURNS turnos VÁLIDOS, na ordem cronológica.
    // Filtra primeiro (descarta inválidos), depois corta o excesso pelo fim.
    const valid: Array<{ role: "user" | "assistant"; text: string }> = [];
    for (const raw of history) {
        if (!raw || typeof raw !== "object") continue;
        const entry = raw as Record<string, unknown>;
        const role = entry.role;
        if (role !== "user" && role !== "assistant") continue;
        const content = typeof entry.content === "string" ? entry.content.trim() : "";
        if (!content) continue;
        valid.push({ role, text: content.slice(0, MAX_HISTORY_TEXT) });
    }
    const recent = valid.slice(-MAX_HISTORY_TURNS);
    for (const turn of recent) {
        items.push(JSON.stringify({
            type: "conversation.item.create",
            item: {
                type: "message",
                role: turn.role,
                content: [{
                    type: turn.role === "user" ? "input_text" : "text",
                    text: turn.text,
                }],
            },
        }));
    }
    return items;
}

Deno.serve((req) => {
    const origin = req.headers.get("origin");
    const corsHeaders = corsFor(origin);
    if (req.method === "OPTIONS") {
        return new Response(null, { headers: corsHeaders });
    }

    const upgrade = (req.headers.get("upgrade") || "").toLowerCase();
    if (upgrade !== "websocket") {
        return new Response(JSON.stringify({ ok: true, service: "darcy-voice" }), {
            headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
    }

    // Bloqueia upgrade WebSocket de origens não-autorizadas (custo xAI Realtime).
    if (!isOriginAllowed(origin)) {
        return new Response("Forbidden origin", { status: 403, headers: corsHeaders });
    }

    const XAI_API_KEY = Deno.env.get("XAI_API_KEY");
    if (!XAI_API_KEY) {
        return new Response("XAI_API_KEY not set", { status: 500, headers: corsHeaders });
    }

    const { socket: client, response } = Deno.upgradeWebSocket(req);

    // deno-lint-ignore no-explicit-any
    let upstream: any = null;
    let sessionReady = false;
    let initialized = false;
    let moodleState: MoodleContextState | null = null;
    let responseActive = false;                       // xAI tem uma response em andamento
    let pendingToolOutput: { callId: string; output: string } | null = null;  // aguardando response.done
    const pendingClientMessages: string[] = [];
    // US-016: turnos do histórico de texto (conversation.item.create) prontos pra
    // semear a sessão xAI. Preenchido no darcy.init a partir de parsed.history;
    // injetado em openUpstream APÓS o session.update e o darcy.ready, ANTES de
    // liberar as mensagens bufferizadas do cliente. Vazio = comportamento inalterado.
    let historySeedItems: string[] = [];

    // ── Estado de TELEMETRIA da sessão (US-011) ──────────────────────────────
    // Modelo escolhido: 1 turno = 1 ciclo de fala (transcrição do usuário ->
    // resposta do assistente). Acumulamos os transcripts que o xAI já manda
    // (input_audio_transcription.completed = fala do usuário;
    //  response.audio_transcript.done = resposta falada) e, ao fechar a response
    // (response.done/completed), gravamos o turno em telemetry_turns. Metadados
    // de sessão (origem, papel, curso, consentimento, voz) são resolvidos uma vez
    // no darcy.init. recordTurnBackground roda em background e nunca derruba a voz.
    // deno-lint-ignore no-explicit-any
    let telSupabase: any = null;                      // service_role para gravar + consentimento
    const tel = {
        sessionId: crypto.randomUUID() as string,     // 1 sessão de voz = 1 conexão WS
        turnIndex: 0,
        userId: null as string | null,                // UUID do usuário (tabela users), resolvido no init
        moodleUserId: null as number | null,
        moodleOrigin: null as string | null,
        darcyMode: "support" as string,               // support | course (kill-switch força support no piloto)
        verifiedRole: null as string | null,
        courseId: null as number | null,
        userFullName: null as string | null,          // p/ redação de PII
        contentConsent: true,                          // opt-out resolvido no init
        modelUsed: "xai-realtime" as string,           // 'xai-realtime-<voice>' após sanitizeVoice
    };
    // Transcript acumulado do ciclo de fala atual (resetado a cada response.done).
    let pendingUserTranscript = "";
    let pendingAssistantTranscript = "";
    let turnStartedAt = 0;                             // marca quando a fala do usuário foi capturada

    // Grava o turno de voz acumulado (best-effort, background). Espelha o padrão
    // do texto (buildTurnRecord + recordTurn), adaptado ao realtime: llm=null
    // (não há cadeia OpenRouter), model_used identifica a voz xAI, latência = do
    // fim da fala do usuário ao fim da resposta. is_error_turn quando aplicável.
    const flushVoiceTurn = (opts: { isError?: boolean; errorDetail?: string | null } = {}): void => {
        const userMsg = pendingUserTranscript.trim();
        const asstMsg = pendingAssistantTranscript.trim();
        // Nada dito de lado a lado e sem erro -> nada a registrar (evita turnos vazios).
        if (!opts.isError && !userMsg && !asstMsg) {
            pendingUserTranscript = "";
            pendingAssistantTranscript = "";
            turnStartedAt = 0;
            return;
        }
        const latencyMs = turnStartedAt > 0 ? Date.now() - turnStartedAt : 0;
        const idx = tel.turnIndex++;
        // Reset imediato pro próximo ciclo (a gravação usa as cópias locais).
        pendingUserTranscript = "";
        pendingAssistantTranscript = "";
        turnStartedAt = 0;
        try {
            const rec = buildTurnRecord({
                turnId: crypto.randomUUID(),
                sessionId: tel.sessionId,
                turnIndex: idx,
                userId: tel.userId,
                moodleUserId: tel.moodleUserId,
                moodleOrigin: tel.moodleOrigin,
                darcyMode: tel.darcyMode,
                verifiedRole: tel.verifiedRole,
                courseId: tel.courseId,
                userMessage: userMsg,
                assistantMessage: asstMsg,
                systemPrompt: "",                       // instructions já contabilizadas; não duplica conteúdo enorme por turno
                conversationWindow: [],
                userFullName: tel.userFullName,
                contentConsent: tel.contentConsent,
                llm: null,                              // voz não passa pela cascata OpenRouter
                latencyMs,
                isErrorTurn: !!opts.isError,
                errorDetail: opts.errorDetail ?? null,
            });
            // model_used vem de llm quando há cadeia; na voz não há, então setamos
            // direto e re-validamos (buildTurnRecord rodou validateTurn com model_used
            // ainda null e marcaria valid=false; aqui corrigimos o veredito).
            rec.model_used = tel.modelUsed;
            const errs = validateTurn(rec);
            rec.valid = errs.length === 0;
            rec.validation_errors = errs.length ? { errors: errs } : null;
            recordTurnBackground(telSupabase, rec);
        } catch (e) {
            // NUNCA derruba a sessão de voz por causa de telemetria.
            console.warn("[darcy-voice] flushVoiceTurn falhou:", e instanceof Error ? e.message : String(e));
        }
    };

    const sendToClient = (payload: unknown) => {
        try {
            if (client.readyState === 1) {
                client.send(typeof payload === "string" ? payload : JSON.stringify(payload));
            }
        } catch { /* ignore */ }
    };

    const openUpstream = (instructions: string, voiceId: VoiceId) => {
        try {
            upstream = new WebSocket("wss://api.x.ai/v1/realtime", {
                headers: { Authorization: `Bearer ${XAI_API_KEY}` },
            });
        } catch (err) {
            console.error("[darcy-voice] failed to open upstream", err);
            sendToClient({ type: "darcy.error", error: "Falha ao conectar com xAI" });
            try { client.close(1011, "upstream_failed"); } catch { /* ignore */ }
            return;
        }

        upstream.on("open", () => {
            const tools = buildVoiceToolDefs(moodleState);
            upstream.send(JSON.stringify({
                type: "session.update",
                session: {
                    voice: voiceId,
                    instructions,
                    input_audio_format: "pcm16",
                    output_audio_format: "pcm16",
                    input_audio_transcription: { model: "whisper-1" },
                    turn_detection: {
                        type: "server_vad",
                        threshold: 0.5,
                        silence_duration_ms: 600,
                        prefix_padding_ms: 300,
                        create_response: true,
                    },
                    tools,
                    tool_choice: tools.length > 0 ? "auto" : "none",
                },
            }));
            sessionReady = true;
            sendToClient({ type: "darcy.ready" });

            // ── Semeia o histórico texto→voz (US-016) ────────────────────────
            // ORDEM: depois do session.update (sessão já configurada) e LOGO APÓS
            // o darcy.ready, mas ANTES de liberar as mensagens bufferizadas do
            // cliente (pendingClientMessages). Assim a sessão xAI já carrega o
            // contexto da conversa de texto quando o usuário começar a falar.
            // Cada turno é um conversation.item.create (sem response.create — não
            // queremos que a IA responda ao histórico, só popular o contexto).
            if (historySeedItems.length > 0) {
                console.log(`[darcy-voice] semeando ${historySeedItems.length} turno(s) de histórico texto→voz`);
                for (const item of historySeedItems) {
                    try { upstream.send(item); } catch (err) {
                        console.warn("[darcy-voice] falha ao semear turno de histórico:", err instanceof Error ? err.message : String(err));
                    }
                }
                historySeedItems = [];
            }

            for (const msg of pendingClientMessages) {
                try { upstream.send(msg); } catch { /* ignore */ }
            }
            pendingClientMessages.length = 0;
        });

        upstream.on("message", (raw: unknown) => {
            const txt = typeof raw === "string"
                ? raw
                : (raw && typeof (raw as { toString: () => string }).toString === "function")
                    ? (raw as { toString: (enc: string) => string }).toString("utf-8")
                    : "";
            if (!txt) return;

            // Intercepta function calls + trackia o ciclo de vida das responses.
            try {
                const evt = JSON.parse(txt) as Record<string, unknown>;
                const et = evt?.type;

                if (et === "response.created") {
                    responseActive = true;
                }
                // ── TELEMETRIA (US-011): captura transcripts do ciclo de fala ──
                // Fala do usuário (whisper server-side): marca o início do turno.
                if (et === "conversation.item.input_audio_transcription.completed") {
                    const t = typeof evt.transcript === "string" ? evt.transcript : "";
                    if (t) {
                        pendingUserTranscript = pendingUserTranscript
                            ? `${pendingUserTranscript} ${t}`.trim()
                            : t;
                        if (turnStartedAt === 0) turnStartedAt = Date.now();
                    }
                }
                // Resposta falada do assistente (transcript da TTS).
                if (et === "response.audio_transcript.done" || et === "response.output_audio_transcript.done") {
                    const t = typeof evt.transcript === "string" ? evt.transcript : "";
                    if (t) {
                        pendingAssistantTranscript = pendingAssistantTranscript
                            ? `${pendingAssistantTranscript} ${t}`.trim()
                            : t;
                    }
                }
                if (et === "response.done" || et === "response.completed") {
                    responseActive = false;
                    // Se há tool output pendente (ainda não enviado porque response estava ativa),
                    // envia agora que fechou. NÃO fecha o turno ainda: o ciclo só termina na
                    // response seguinte (a que contém a fala do assistente após a tool).
                    if (pendingToolOutput) {
                        const { callId, output } = pendingToolOutput;
                        pendingToolOutput = null;
                        sendToolOutputToUpstream(callId, output);
                    } else {
                        // Fim do ciclo de fala — grava o turno (user -> assistant).
                        flushVoiceTurn();
                    }
                }
                if (et === "error") {
                    // xAI sinalizou erro explícito. LOG TUDO para diagnóstico.
                    console.error(`[darcy-voice] xAI error payload: ${txt.slice(0, 800)}`);
                    // Registra turno de erro com o que já houver de transcript.
                    flushVoiceTurn({ isError: true, errorDetail: txt.slice(0, 500) });
                }
                if (et === "response.function_call_arguments.done") {
                    console.log(`[darcy-voice] xAI solicitou tool: name=${evt.name} call_id=${evt.call_id}`);
                    handleFunctionCall(evt).catch((err) => {
                        console.error("[darcy-voice] handleFunctionCall crashed:", err);
                    });
                }
            } catch { /* não é JSON, só repassa */ }

            sendToClient(txt);
        });

        upstream.on("error", (err: unknown) => {
            const msg = err instanceof Error ? `${err.name}: ${err.message}` : String(err);
            console.error(`[darcy-voice] upstream error: ${msg}`);
            sendToClient({ type: "darcy.error", error: `Erro upstream: ${msg}` });
            try { client.close(1011, "upstream_error"); } catch { /* ignore */ }
        });

        upstream.on("close", (code?: number, reason?: unknown) => {
            const reasonStr = typeof reason === "string" ? reason : String(reason ?? "");
            console.log(`[darcy-voice] upstream closed code=${code} reason=${reasonStr}`);
            try { client.close(1000, "upstream_closed"); } catch { /* ignore */ }
        });

        upstream.on("unexpected-response", (_req: unknown, res: { statusCode?: number; statusMessage?: string }) => {
            console.error(`[darcy-voice] upstream HTTP reject: ${res?.statusCode} ${res?.statusMessage}`);
            sendToClient({ type: "darcy.error", error: `xAI rejeitou conexão: HTTP ${res?.statusCode}` });
        });
    };

    // Limite do output: xAI tem limite de token no function_call_output.
    // 1800 chars ≈ 600 tokens — suficiente para uma lista razoável sem estourar.
    const MAX_TOOL_OUTPUT = 1800;

    function sendToolOutputToUpstream(callId: string, output: string): void {
        if (!upstream || upstream.readyState !== 1) {
            console.error(`[darcy-voice] upstream não disponível para enviar output (callId=${callId})`);
            return;
        }
        try {
            const truncated = output.length > MAX_TOOL_OUTPUT
                ? output.slice(0, MAX_TOOL_OUTPUT) + "\n… (saída truncada)"
                : output;
            console.log(`[darcy-voice] enviando function_call_output callId=${callId} bytes=${truncated.length}`);
            upstream.send(JSON.stringify({
                type: "conversation.item.create",
                item: {
                    type: "function_call_output",
                    call_id: callId,
                    output: truncated,
                },
            }));
            upstream.send(JSON.stringify({ type: "response.create" }));
            responseActive = true;
        } catch (err) {
            console.error("[darcy-voice] falha ao enviar tool output:", err);
        }
    }

    async function handleFunctionCall(evt: Record<string, unknown>): Promise<void> {
        const t0 = Date.now();
        const callId = typeof evt.call_id === "string" ? evt.call_id : "";
        const name = typeof evt.name === "string" ? evt.name : "";
        let parsedArgs: Record<string, unknown> = {};
        if (typeof evt.arguments === "string") {
            try { parsedArgs = JSON.parse(evt.arguments); } catch { parsedArgs = {}; }
        }
        // Higiene de log (LGPD): só nome/call_id, sem valores dos args (podem conter PII).
        console.log(`[darcy-voice] tool ${name} call_id=${callId} args.keys=[${Object.keys(parsedArgs).join(",")}]`);

        let output: string;
        try {
            if (REGISTRY_TOOL_NAMES.has(name)) {
                // Tool do registry COMPARTILHADO: passa pelo executeTool de ../_shared/tools.ts
                // (mesmos guards do texto: STUDENT_BLOCKED_TOOLS, enforce courseId, SSRF).
                // O executor recebe { moodleBase, moodleToken, supabase, context } resolvidos
                // do moodleState. O resultado pode ser objeto OU string — serializa pra fala.
                const result = moodleState
                    ? await executeTool(name, parsedArgs, moodleState.base, moodleState.token, moodleState.supabase, moodleState.context)
                    : { error: "Moodle não disponível nesta sessão." };
                output = typeof result === "string" ? result : JSON.stringify(result);

