// Testes da camada determinística de reparo de texto (text-repair.ts).
// Rodar: deno test supabase/functions/_shared/text-repair.test.ts
import { assertEquals } from "https://deno.land/std@0.224.0/assert/mod.ts";
import { repairPortugueseText } from "./text-repair.ts";

const fix = (s: string) => repairPortugueseText(s).text;

Deno.test("separa palavras grudadas reais (casos do piloto)", () => {
    assertEquals(fix("**Resposta diretae passo a passo:**"), "**Resposta direta e passo a passo:**");
    assertEquals(fix("Dúvidas de conteúdoacadêmico hoje"), "Dúvidas de conteúdo acadêmico hoje");
    assertEquals(fix("Qual éa mensagem de erro?"), "Qual é a mensagem de erro?");
    assertEquals(fix("personalizar otema do curso"), "personalizar o tema do curso");
});

Deno.test("conserta espaçamento de pontuação", () => {
    assertEquals(fix("passo:Dúvidas frequentes"), "passo: Dúvidas frequentes");
    assertEquals(fix("primeiro passo.Dúvidas"), "primeiro passo. Dúvidas");
});

Deno.test("NÃO altera texto já correto", () => {
    const ok = "Para personalizar o tema do seu curso, acesse Preferências.";
    assertEquals(fix(ok), ok);
    const ok2 = "Você vai aprender também com o professor na disciplina.";
    assertEquals(fix(ok2), ok2);
});

Deno.test("NÃO divide palavras legítimas/estrangeiras nem números", () => {
    assertEquals(fix("faça login e veja o feedback online no site"), "faça login e veja o feedback online no site");
    assertEquals(fix("O valor é 1,5 e o horário 12:30 com pi=3.14"), "O valor é 1,5 e o horário 12:30 com pi=3.14");
    assertEquals(fix("Seu CPF e a UnB no Moodle"), "Seu CPF e a UnB no Moodle");
});

Deno.test("preserva código inline, blocos e URLs", () => {
    const s = "Rode `git status` e veja https://aprender2.unb.br/login agora";
    assertEquals(fix(s), s);
});

Deno.test("é idempotente", () => {
    const once = fix("conteúdoacadêmico otema diretae éa");
    assertEquals(fix(once), once);
    assertEquals(once, "conteúdo acadêmico o tema direta e é a");
});

