// ── Roteador determinístico (sem IA, sem vetor): escolhe seções por palavra-chave ──

// Normaliza para casamento robusto: minúsculas, sem acentos, só [a-z0-9], espaço e "/".
function normalize(s: string): string {
    return (s || "")
        .toLowerCase()
        .normalize("NFD")
        .replace(/[̀-ͯ]/g, "")     // remove diacríticos
        .replace(/[^a-z0-9/ ]+/g, " ")
        .replace(/\s+/g, " ")
        .trim();
}

function escapeRegex(s: string): string {
    return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

// Casa uma keyword no "palheiro". Frases e fragmentos de caminho (com espaço ou "/")
// usam substring; tokens únicos usam fronteira de palavra (evita "nota" em "anotacao").
function matchKeyword(hay: string, kw: string): boolean {
    const k = normalize(kw);
    if (!k) return false;
    if (k.includes(" ") || k.includes("/")) return hay.includes(k);
    return new RegExp(`(^|[^a-z0-9])${escapeRegex(k)}([^a-z0-9]|$)`).test(hay);
}

function audienceMatchesRole(audience: MoodleAudience, role?: string | null): boolean {
    if (audience === "ambos") return true;
    if (!role) return true;
    if (role === "teacher") return audience === "professor";
    if (role === "student") return audience === "aluno";
    return true;
}

// Extrai texto útil do pageContext (onde o usuário está / o que vê na tela).
function pageContextText(pageContext: any): string {
    if (!pageContext || typeof pageContext !== "object") return "";
    const parts: string[] = [];
    const push = (v: unknown) => { if (typeof v === "string" && v) parts.push(v); };
    push(pageContext.pageTitle);
    push(pageContext.pageHeading);
    push(pageContext.activityName);
    push(pageContext.sectionName);
    push(pageContext.url);
    if (Array.isArray(pageContext.breadcrumb)) for (const b of pageContext.breadcrumb) push(b);
    return parts.join(" ");
}

export interface ScoredSection { section: MoodleSection; score: number; }

// Pontua e ordena as seções pela relevância à pergunta + contexto da página.
export function selectMoodleSections(
    query: string,
    pageContext?: any,
    role?: string | null,
    max = 2
): MoodleSection[] {
    const hay = normalize(`${query || ""} ${pageContextText(pageContext)}`);
    if (!hay) return [];

    const scored: ScoredSection[] = [];
    for (const section of MOODLE_SECTIONS) {
        let score = 0;
        for (const kw of section.keywords) {
            if (matchKeyword(hay, kw)) {
                const k = normalize(kw);
                score += (k.length >= 5 || k.includes("/")) ? 2 : 1; // termos longos/caminhos pesam mais
            }
        }
        if (score === 0) continue;
        if (audienceMatchesRole(section.audience, role)) score += 1; // leve preferência pelo papel
        scored.push({ section, score });
    }

    scored.sort((a, b) => b.score - a.score);
    return scored.slice(0, Math.max(0, max)).map((s) => s.section);
}

// Monta o bloco <moodle_docs> para injetar no system prompt: índice-núcleo SEMPRE +
// o detalhe das seções relevantes (quando houver). String vazia nunca acontece —
// o índice garante que o Darcy sempre saiba que domina o Moodle.
export function buildMoodleKnowledgeBlock(
    query: string,
    pageContext?: any,
    role?: string | null,
    maxSections = 2
): string {
    const picked = selectMoodleSections(query, pageContext, role, maxSections);

    let detail = "";
    if (picked.length > 0) {
        detail = "\n\nDETALHE RELEVANTE para esta conversa (use o passo a passo e cite o link oficial quando útil):\n" +
            picked.map((s) => `## ${s.title}\nDoc oficial: ${s.doc}\n${s.body}`).join("\n\n");
    }

    return `<moodle_docs source="Documentação oficial do Moodle (docs.moodle.org)" authority="high">
Além do suporte do CEAD, você é ESPECIALISTA no Moodle (o AVA). Oriente o usuário em QUALQUER funcionalidade do Moodle com o passo a passo de "onde clicar", usando os rótulos reais da interface. Quando fizer sentido, indique a página oficial (docs.moodle.org) para aprofundar. Se a pergunta for de CONTEÚDO acadêmico (a matéria em si), aí sim redirecione ao professor — orientação de USO da plataforma é com você.

${MOODLE_CORE_INDEX}${detail}
</moodle_docs>`;
}

