// Testes do roteador determinístico da base de conhecimento Moodle.
// Rodar: deno test supabase/functions/_shared/moodle-knowledge.test.ts
import { assert, assertEquals } from "https://deno.land/std@0.224.0/assert/mod.ts";
import {
    selectMoodleSections,
    buildMoodleKnowledgeBlock,
    MOODLE_SECTIONS,
} from "./moodle-knowledge.ts";

const routesTo = (q: string, expectId: string, role?: string, ctx?: unknown) =>
    selectMoodleSections(q, ctx, role, 2).map((s) => s.id).includes(expectId);

Deno.test("roteia perguntas comuns para a seção certa", () => {
    assert(routesTo("como eu envio minha tarefa?", "enviar-tarefa"));
    assert(routesTo("esqueci minha senha, não consigo entrar", "login-e-acesso"));
    assert(routesTo("onde vejo minhas notas?", "ver-minhas-notas"));
    assert(routesTo("como uso o app no celular", "app-moodle-celular"));
    assert(routesTo("como matriculo alunos no curso", "matricular-usuarios-participantes", "teacher"));
