import { useState, type FormEvent } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Loader2, Lock } from "lucide-react";

/**
 * Pagina de login do dashboard (US-017).
 *
 * Metodo: Supabase Auth email + senha (signInWithPassword). Escolhido por ser o
 * mais simples e robusto para o piloto: nao depende de entrega de e-mail/SMTP nem
 * de clicar em link (como o magic link), e os usuarios do CEAD sao provisionados
 * server-side no Supabase Auth (ver checklist de deploy US-020).
 *
 * Este componente apenas autentica e cria a sessao Supabase. O gate de rota e o
 * ProtectedRoute; a ALLOWLIST de quem pode ler PII e aplicada NO SERVIDOR pela
 * dashboard-api (US-016). Aqui o gate e somente "ha sessao autenticada".
 */
const Login = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Para onde voltar apos o login (rota que o usuario tentou acessar sem sessao).
  const from =
    (location.state as { from?: string } | null)?.from ?? "/dashboard";

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    if (loading) return;
    setError(null);
    setLoading(true);
    try {
      const { error: signInError } = await supabase.auth.signInWithPassword({
        email: email.trim(),
        password,
      });
      if (signInError) {
        setError("E-mail ou senha invalidos.");
        return;
      }
      // Sessao criada; ProtectedRoute reage via onAuthStateChange, mas
      // navegamos explicitamente para a rota de origem para UX imediata.
      navigate(from, { replace: true });
    } catch {
      setError("Nao foi possivel conectar. Tente novamente.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="dark min-h-screen flex items-center justify-center bg-[#0A0A0A] text-white px-4 font-sans">
      {/* Ambient glow, alinhado ao visual do Dashboard */}
      <div className="fixed inset-0 pointer-events-none overflow-hidden flex justify-center">
        <div className="w-[800px] h-[500px] bg-emerald-500/10 blur-[130px] rounded-full absolute -top-[100px] opacity-40 mix-blend-screen" />
        <div className="w-[600px] h-[400px] bg-blue-500/10 blur-[120px] rounded-full absolute top-[20%] -left-[10%] opacity-20 mix-blend-screen" />
      </div>

      <Card className="relative z-10 w-full max-w-sm bg-[#121212] border-white/10 text-white shadow-2xl">
        <CardHeader className="space-y-2">
          <div className="flex items-center gap-2">
            <span className="text-2xl font-bold tracking-tighter text-white">
              Darcy
            </span>
            <span className="text-2xl font-light tracking-tight text-white/50">
              Analytics
            </span>
          </div>
          <CardTitle className="text-lg font-semibold flex items-center gap-2">
            <Lock className="h-4 w-4 text-emerald-400" />
            Acesso restrito
          </CardTitle>
          <CardDescription className="text-white/50">
            Entre com sua conta para ver o painel.
          </CardDescription>
        </CardHeader>

        <form onSubmit={handleSubmit}>
          <CardContent className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="email" className="text-white/70">
                E-mail
              </Label>
              <Input
                id="email"
                type="email"
                autoComplete="email"
                required
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="voce@unb.br"
                className="bg-white/5 border-white/10 text-white placeholder:text-white/30"
                disabled={loading}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="password" className="text-white/70">
                Senha
              </Label>
              <Input
                id="password"
                type="password"
                autoComplete="current-password"
                required
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="••••••••"
                className="bg-white/5 border-white/10 text-white placeholder:text-white/30"
                disabled={loading}
              />
            </div>

            {error && (
              <p
                role="alert"
                className="text-sm text-red-400 bg-red-500/10 border border-red-500/20 rounded-md px-3 py-2"
              >
                {error}
              </p>
            )}
          </CardContent>

          <CardFooter>
            <Button
              type="submit"
              className="w-full bg-emerald-500 hover:bg-emerald-600 text-black font-semibold"
              disabled={loading || !email || !password}
            >
              {loading ? (
                <>
                  <Loader2 className="h-4 w-4 animate-spin" />
                  Entrando...
                </>
              ) : (
                "Entrar"
              )}
            </Button>
          </CardFooter>
        </form>
      </Card>
    </div>
  );
};

export default Login;

