1	// index.ts - dashboard-api
2	// Proxy de LEITURA do dashboard (PII de alunos + analytics) via service_role,
3	// autenticado por Supabase Auth (JWT). Allowlist de e-mails e OPCIONAL.
4	//
5	// POR QUE ESTA FUNCTION EXISTE (bloqueador B1/B2 — lado servidor do dashboard):
6	// Antes o dashboard React lia users/chat_sessions/messages/analytics_* DIRETO via
7	// PostgREST com a anon key (publica). Como a anon key e embarcada no bundle do
8	// dashboard, qualquer pessoa podia enumerar PII de todos os alunos. Apos o lockdown
9	// de RLS (US-002), essas tabelas ficam deny-anon e TODA leitura do dashboard passa
10	// por AQUI, usando SUPABASE_SERVICE_ROLE_KEY (bypassa RLS) — mas SO depois de:
11	//   1. Validar o access_token do Supabase Auth (Authorization: Bearer <jwt>) via
12	//      supabase.auth.getUser(jwt). Sem token valido -> 401.
13	//   2. (OPCIONAL) Se houver allowlist configurada (env DASHBOARD_ALLOWED_EMAILS
14	//      OU linhas em public.dashboard_allowlist), o e-mail precisa estar nela; senao
15	//      -> 403. Se a allowlist estiver vazia/ausente, qualquer usuario AUTENTICADO
16	//      entra. Decisao do projeto: o controle de acesso e "ter conta no Supabase
17	//      Auth", e a trava equivalente e DESLIGAR o cadastro publico (invite-only).
18	// So depois disso a function executa LEITURAS (nunca escrita) com service_role.
19	//
20	// MODELO: a function expõe um proxy de query CONSTRITO por ?resource=<tabela>, com
21	// uma allowlist fixa de tabelas/views e de filtros suportados, replicando os
22	// selects/filtros que os hooks do dashboard usam hoje (useUsers, useAnalytics,
23	// useAdvancedAnalytics, OverviewMetrics). Nada de escrita; nada de tabela fora da
24	// allowlist; nada de SQL arbitrario.
25	
26	import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
27	
28	// ── CORS whitelist (dashboard Vercel + localhost) ───────────────────────────
29	// SECURITY: match EXATO de origin (nao startsWith) para evitar bypass do tipo
30	// `https://meu-dashboard.vercel.app.evil.com`. localhost de QUALQUER porta e
31	// aceito via parse de URL (hostname === 'localhost'/'127.0.0.1'), nao por prefixo.
32	//
33	// !!! AJUSTAR NO DEPLOY (US-020) !!!
34	// Trocar/confirmar o(s) dominio(s) Vercel reais do dashboard abaixo. O placeholder
35	// 'https://darcy-dashboard.vercel.app' e um CHUTE — o dominio exato do projeto
36	// Vercel deve ser colocado aqui (ou movido para a env DASHBOARD_ALLOWED_ORIGINS
37	// csv, ja suportada abaixo) antes de liberar o dashboard em producao.
38	const STATIC_ALLOWED_ORIGINS = [
39	    'https://darcy-dashboard.vercel.app', // <-- PLACEHOLDER: ajustar p/ dominio Vercel real no deploy
40	];
41	
42	// Origens extras via env (csv). Ex.: DASHBOARD_ALLOWED_ORIGINS="https://abc.vercel.app,https://dash.cead.unb.br"
43	function envAllowedOrigins(): string[] {
44	    const raw = Deno.env.get('DASHBOARD_ALLOWED_ORIGINS') || '';
45	    return raw.split(',').map(s => s.trim()).filter(Boolean);
46	}
47	
48	function isOriginAllowed(origin: string): boolean {
49	    if (!origin) return false;
50	    const list = [...STATIC_ALLOWED_ORIGINS, ...envAllowedOrigins()];
51	    if (list.includes(origin)) return true;
52	    try {
53	        const u = new URL(origin);
54	        if ((u.protocol === 'http:' || u.protocol === 'https:') &&
55	            (u.hostname === 'localhost' || u.hostname === '127.0.0.1')) {
56	            return true;
57	        }
58	    } catch {
59	        // origin malformado -> nao permitido
60	    }
61	    return false;
62	}
63	
64	function getCorsHeaders(origin?: string): Record<string, string> {
65	    // API autenticada por Bearer token (Supabase Auth), SEM cookies. O token e a
66	    // fronteira de seguranca, nao a origem — entao refletimos a origem do chamador
67	    // (ou *). Isso evita depender de cadastrar o dominio do dashboard (Vercel).
68	    // isOriginAllowed/envAllowedOrigins ficam disponiveis caso se queira travar por
69	    // origem no futuro (setar DASHBOARD_ALLOWED_ORIGINS e voltar a gatear aqui).
70	    void isOriginAllowed;
