// index.ts - dashboard-api
// Proxy de LEITURA do dashboard (PII de alunos + analytics) via service_role,
// autenticado por Supabase Auth (JWT). Allowlist de e-mails e OPCIONAL.
//
// POR QUE ESTA FUNCTION EXISTE (bloqueador B1/B2 — lado servidor do dashboard):
// Antes o dashboard React lia users/chat_sessions/messages/analytics_* DIRETO via
// PostgREST com a anon key (publica). Como a anon key e embarcada no bundle do
// dashboard, qualquer pessoa podia enumerar PII de todos os alunos. Apos o lockdown
// de RLS (US-002), essas tabelas ficam deny-anon e TODA leitura do dashboard passa
// por AQUI, usando SUPABASE_SERVICE_ROLE_KEY (bypassa RLS) — mas SO depois de:
//   1. Validar o access_token do Supabase Auth (Authorization: Bearer <jwt>) via
//      supabase.auth.getUser(jwt). Sem token valido -> 401.
//   2. (OPCIONAL) Se houver allowlist configurada (env DASHBOARD_ALLOWED_EMAILS
//      OU linhas em public.dashboard_allowlist), o e-mail precisa estar nela; senao
//      -> 403. Se a allowlist estiver vazia/ausente, qualquer usuario AUTENTICADO
//      entra. Decisao do projeto: o controle de acesso e "ter conta no Supabase
//      Auth", e a trava equivalente e DESLIGAR o cadastro publico (invite-only).
// So depois disso a function executa LEITURAS (nunca escrita) com service_role.
//
// MODELO: a function expõe um proxy de query CONSTRITO por ?resource=<tabela>, com
// uma allowlist fixa de tabelas/views e de filtros suportados, replicando os
// selects/filtros que os hooks do dashboard usam hoje (useUsers, useAnalytics,
// useAdvancedAnalytics, OverviewMetrics). Nada de escrita; nada de tabela fora da
// allowlist; nada de SQL arbitrario.

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

// ── CORS whitelist (dashboard Vercel + localhost) ───────────────────────────
// SECURITY: match EXATO de origin (nao startsWith) para evitar bypass do tipo
// `https://meu-dashboard.vercel.app.evil.com`. localhost de QUALQUER porta e
// aceito via parse de URL (hostname === 'localhost'/'127.0.0.1'), nao por prefixo.
//
// !!! AJUSTAR NO DEPLOY (US-020) !!!
// Trocar/confirmar o(s) dominio(s) Vercel reais do dashboard abaixo. O placeholder
// 'https://darcy-dashboard.vercel.app' e um CHUTE — o dominio exato do projeto
// Vercel deve ser colocado aqui (ou movido para a env DASHBOARD_ALLOWED_ORIGINS
// csv, ja suportada abaixo) antes de liberar o dashboard em producao.
const STATIC_ALLOWED_ORIGINS = [
    'https://darcy-dashboard.vercel.app', // <-- PLACEHOLDER: ajustar p/ dominio Vercel real no deploy
];

// Origens extras via env (csv). Ex.: DASHBOARD_ALLOWED_ORIGINS="https://abc.vercel.app,https://dash.cead.unb.br"
function envAllowedOrigins(): string[] {
    const raw = Deno.env.get('DASHBOARD_ALLOWED_ORIGINS') || '';
    return raw.split(',').map(s => s.trim()).filter(Boolean);
}

function isOriginAllowed(origin: string): boolean {
    if (!origin) return false;
    const list = [...STATIC_ALLOWED_ORIGINS, ...envAllowedOrigins()];
    if (list.includes(origin)) return true;
    try {
        const u = new URL(origin);
        if ((u.protocol === 'http:' || u.protocol === 'https:') &&
            (u.hostname === 'localhost' || u.hostname === '127.0.0.1')) {
            return true;
        }
    } catch {
        // origin malformado -> nao permitido
    }
    return false;
}

function getCorsHeaders(origin?: string): Record<string, string> {
    // API autenticada por Bearer token (Supabase Auth), SEM cookies. O token e a
    // fronteira de seguranca, nao a origem — entao refletimos a origem do chamador
    // (ou *). Isso evita depender de cadastrar o dominio do dashboard (Vercel).
    // isOriginAllowed/envAllowedOrigins ficam disponiveis caso se queira travar por
    // origem no futuro (setar DASHBOARD_ALLOWED_ORIGINS e voltar a gatear aqui).
    void isOriginAllowed;
    return {
        'Access-Control-Allow-Origin': origin || '*',
        'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
        'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
        'Vary': 'Origin',
    };
}

function jsonResponse(body: unknown, status: number, cors: Record<string, string>): Response {
    return new Response(JSON.stringify(body), {
        status,
        headers: { ...cors, 'Content-Type': 'application/json' },
    });
}

// ── Rate limit (in-memory, por usuario/IP) — mesmo padrao das outras functions ─
const rateLimitMap = new Map<string, { count: number; resetAt: number }>();
const RATE_LIMIT = 120;          // 120 req/min/chave (dashboard faz polling de varios cards)
const RATE_WINDOW_MS = 60_000;
function checkRateLimit(key: string): boolean {
    const now = Date.now();
    const entry = rateLimitMap.get(key);
    if (!entry || now > entry.resetAt) {
        rateLimitMap.set(key, { count: 1, resetAt: now + RATE_WINDOW_MS });
        if (rateLimitMap.size > 5000) {
            for (const [k, v] of rateLimitMap) { if (now > v.resetAt) rateLimitMap.delete(k); }
        }
        return true;
    }
    if (entry.count >= RATE_LIMIT) return false;
    entry.count++;
    return true;
}

