        <Toaster />
        <Sonner />
        <BrowserRouter>
          <Routes>
            {/* Rota publica: login. */}
            <Route path="/login" element={<Login />} />
            {/* Rotas protegidas: so montam com sessao Supabase Auth ativa. */}
            <Route
              path="/dashboard"
              element={
                <ProtectedRoute>
                  <Dashboard />
                </ProtectedRoute>
              }
            />
            <Route path="*" element={<Navigate to="/dashboard" replace />} />
          </Routes>
        </BrowserRouter>
      </TooltipProvider>
    </ThemeProvider>
  </QueryClientProvider>
);

export default App;

