if (req.method === 'OPTIONS') {
  return new Response(null, { headers: cors });
}

try {
  const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
  const supabaseKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
  const supabase = createClient(supabaseUrl, supabaseKey);

  const { event_type, data } = await req.json();

  // Rate limit por browser_id (cai pra IP se não vier browser_id)
  const rateKey = data?.browser_id
    || req.headers.get('x-forwarded-for')?.split(',')[0]?.trim()
    || 'unknown';
  if (!checkRateLimit(rateKey)) {
    return new Response(JSON.stringify({ success: false, error: 'rate_limited' }), {
      status: 429,
      headers: { ...cors, 'Content-Type': 'application/json' },
    });
  }

  // Normalize moodle_origin: ensure full hostname (e.g. 'aprender2' → 'aprender2.unb.br')
  let rawOrigin = data.moodle_origin || null;
  if (rawOrigin && !rawOrigin.includes('.')) {
    rawOrigin = rawOrigin + '.unb.br';
  }

  // Context fields auto-enriched by widget (available on every event)
  const ctx = {
    moodle_origin: rawOrigin,
    page_url: data.page_url || null,
    page_title: data.page_title || null,
    darcy_mode: data.darcy_mode || 'support',
    browser_id: data.browser_id || null,
    moodle_user_id: data.moodle_user_id ? Number(data.moodle_user_id) : null,
  };

  console.log(`[ANALYTICS] ${event_type} | origin=${ctx.moodle_origin} moodle_id=${ctx.moodle_user_id} browser=${ctx.browser_id?.slice(0, 8)}`);

  // Each handler is wrapped in try-catch so individual failures don't block others
  let handlerError: any = null;

  switch (event_type) {

    // ═══════════════════════════════════════════════════════════════════
    // SESSION LIFECYCLE
    // ═══════════════════════════════════════════════════════════════════

    case 'session_start': {
      const md = data.moodle_data || {};

      // Create or find user.
      // SECURITY (B4): NÃO confiamos em PII vinda do cliente. email/full_name/
      // idnumber/phone1/city/institution chegam no corpo da request e podem ser
      // forjados (envenenamento da tabela users). Só persistimos o VÍNCULO não-PII
      // (moodle_user_id, browser_id) + dados de contexto não sensíveis (username,
      // course_id/name, role). A PII verdadeira é preenchida server-side pelo
      // darcy-chat, que busca do Moodle com wstoken via core_user_get_users
      // (ver darcy-chat/index.ts). Passamos null nos campos de PII para NÃO
      // sobrescrever o que já existe no banco com dados do cliente.
