import { useState, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { OverviewMetrics } from "@/components/dashboard/OverviewMetrics";
import { ConversationMetrics } from "@/components/dashboard/ConversationMetrics";
import { PerformanceMetrics } from "@/components/dashboard/PerformanceMetrics";
import { TemporalMetrics } from "@/components/dashboard/TemporalMetrics";
import { QuestionFrequencyMetrics } from "@/components/dashboard/QuestionFrequencyMetrics";
import { UsersBrowser } from "@/components/dashboard/UsersBrowser";
import { GDPRCompliance } from "@/components/dashboard/GDPRCompliance";
import { TelemetryMetrics } from "@/components/dashboard/TelemetryMetrics";
import { DateRangePicker } from "@/components/dashboard/DateRangePicker";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import {
  BarChart3, Moon, Sun, MessageSquare, Gauge, Clock,
  HelpCircle, Sparkles, BookOpen, Users2, Globe, Radio, Settings2, Command, ChevronRight, LogOut, ShieldCheck, Activity
} from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { useTheme } from "next-themes";
import { cn } from "@/lib/utils";
import { useMoodleOrigins } from "@/hooks/useAnalytics";

export type DarcyMode = "all" | "support" | "course";
export type MoodleOrigin = string;

const PRESETS = [
  { label: "Hoje", days: 0 },
  { label: "7d", days: 7 },
  { label: "30d", days: 30 },
  { label: "3m", days: 90 },
] as const;

function getPresetRange(days: number): { from: Date; to: Date } {
  const to = new Date();
  const from = new Date();
  if (days === 0) { from.setHours(0, 0, 0, 0); }
  else { from.setDate(from.getDate() - days); from.setHours(0, 0, 0, 0); }
  return { from, to };
}

const TABS = [
  { value: "overview", label: "Visão Geral", icon: BarChart3 },
  { value: "users", label: "Público e Usuários", icon: Users2 },
  { value: "conversations", label: "Sessões e Interações", icon: MessageSquare },
  { value: "questions", label: "Tópicos Buscados", icon: HelpCircle },
  { value: "performance", label: "Desempenho", icon: Gauge },
  { value: "temporal", label: "Padrões Temporais", icon: Clock },
  { value: "telemetry", label: "Telemetria", icon: Activity },
  { value: "lgpd", label: "LGPD / Privacidade", icon: ShieldCheck },
] as const;

const MODES = [
  { value: "all" as DarcyMode, label: "Todos Agentes", icon: Sparkles },
  { value: "support" as DarcyMode, label: "Suporte", icon: Settings2 },
  { value: "course" as DarcyMode, label: "Cursos", icon: BookOpen },
] as const;

const Dashboard = () => {
  const [dateRange, setDateRange] = useState(getPresetRange(30));
  const [activePreset, setActivePreset] = useState(30);
  const [darcyMode, setDarcyMode] = useState<DarcyMode>("all");
  const [siteFilter, setSiteFilter] = useState<MoodleOrigin>("all");
  const { theme, setTheme } = useTheme();
  const { data: origins = [] } = useMoodleOrigins();
  const navigate = useNavigate();

  const handlePreset = useCallback((days: number) => {
    setActivePreset(days);
    setDateRange(getPresetRange(days));
  }, []);

  const handleLogout = useCallback(async () => {
    // Encerra a sessao Supabase Auth; o ProtectedRoute reage via
    // onAuthStateChange, mas navegamos explicitamente para UX imediata.
    await supabase.auth.signOut();
    navigate("/login", { replace: true });
  }, [navigate]);

  return (
    <div className="dark min-h-screen bg-[#0A0A0A] text-white selection:bg-emerald-500/30 font-sans tracking-tight">
      {/* Premium ambient glow background */}
      <div className="fixed inset-0 pointer-events-none overflow-hidden flex justify-center">
        <div className="w-[800px] h-[500px] bg-emerald-500/10 blur-[130px] rounded-full absolute -top-[100px] opacity-40 mix-blend-screen" />
        <div className="w-[600px] h-[400px] bg-blue-500/10 blur-[120px] rounded-full absolute top-[20%] -left-[10%] opacity-20 mix-blend-screen" />
      </div>

      <div className="relative mx-auto max-w-[1600px] px-6 md:px-10 py-6 lg:py-8 space-y-8">

        {/* ═══ HEADER REIMAGINED ═══ */}
        <header className="flex flex-col xl:flex-row xl:items-center justify-between gap-6 pb-6 border-b border-white/10 relative z-30">

          {/* Logo & Environment Area (Vercel Style Breadcrumb) */}
          <div className="flex items-center flex-wrap gap-2 sm:gap-4">
            {/* Text Logo */}
            <div className="flex flex-col">
              <div className="flex items-center gap-2">
                <span className="text-xl sm:text-2xl font-bold tracking-tighter text-white">
                  Darcy
                </span>
                <span className="text-xl sm:text-2xl font-light tracking-tight text-white/50">
                  Analytics
                </span>
                <Badge variant="outline" className="ml-2 bg-emerald-500/10 text-emerald-400 border-emerald-500/20 text-[9px] px-1.5 py-0 h-5 rounded-md uppercase tracking-widest font-bold flex items-center gap-1 shadow-[0_0_15px_rgba(16,185,129,0.15)]">
                  <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" /> Ao Vivo
                </Badge>
              </div>
            </div>

            <ChevronRight className="h-4 w-4 text-white/20 hidden sm:block" />

            {/* Origin Environment Select */}
            <Select value={siteFilter} onValueChange={setSiteFilter}>
              <SelectTrigger className="w-[200px] sm:w-[240px] h-9 bg-transparent border-0 hover:bg-white/5 text-white rounded-lg transition-colors focus:ring-0 shadow-none px-2 sm:-ml-2">
                <div className="flex items-center gap-2 text-sm font-medium">
                  <Globe className="h-4 w-4 text-white/40 flex-shrink-0" />
                  <span className="truncate flex-1 text-left">
                    <SelectValue placeholder="Todos os Ambientes" />
                  </span>
                </div>
              </SelectTrigger>
              <SelectContent className="bg-[#121212] border-white/10 text-white backdrop-blur-xl rounded-xl shadow-2xl z-[100]">
                <SelectItem value="all" className="text-xs focus:bg-white/10 focus:text-white cursor-pointer rounded-lg mx-1 my-0.5">
                  Todos os Ambientes
                </SelectItem>
                {origins.map((o) => (
                  <SelectItem key={o} value={o} className="text-xs focus:bg-white/10 focus:text-white cursor-pointer rounded-lg mx-1 my-0.5" title={o}>
                    {o.length > 30 ? o.substring(0, 30) + '...' : o}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Controls Bar (Right Side) */}
          <div className="flex flex-wrap items-center gap-3">

            {/* Context/Mode Toggle Group */}
            <div className="flex items-center p-1 bg-white/5 backdrop-blur-md rounded-xl border border-white/10 whitespace-nowrap overflow-x-auto no-scrollbar max-w-full">
              {MODES.map((m) => {
                const Icon = m.icon;
                const active = darcyMode === m.value;
                return (
                  <button key={m.value} onClick={() => setDarcyMode(m.value)}
                    className={cn(
                      "flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-semibold transition-all duration-300",
                      active
                        ? "bg-white text-black shadow-md"
                        : "text-white/40 hover:text-white hover:bg-white/5"
                    )}>
                    <Icon className={cn("h-3.5 w-3.5", active ? "text-black" : "")} /> 
                    <span className="hidden sm:inline-block">{m.label}</span>
                  </button>
                );
              })}
            </div>

            {/* Date Range Group */}
            <div className="flex items-center p-1 bg-white/5 backdrop-blur-md rounded-xl border border-white/10 overflow-x-auto no-scrollbar relative [&_.popover-content]:!z-[100]">
              <div className="flex px-1 gap-1">
                {PRESETS.map((p) => (
                  <button key={p.days} onClick={() => handlePreset(p.days)}
                    className={cn(
                      "px-3 py-1.5 rounded-lg text-xs font-semibold transition-all duration-300 flex-shrink-0",
                      activePreset === p.days
                        ? "bg-emerald-500/20 text-emerald-400 border border-emerald-500/30 shadow-sm"
                        : "text-white/40 hover:text-white hover:bg-white/5"
                    )}>{p.label}</button>
                ))}
              </div>

              <div className="w-px h-4 bg-white/10 mx-1 flex-shrink-0" />

              <div className="bg-transparent border-0 [&>button]:border-none [&>button]:bg-transparent [&>button]:shadow-none [&>button]:text-white/80 [&>button:hover]:text-white [&>button:hover]:bg-white/5 [&>button]:h-8 [&>button]:px-2 font-mono">
                 <DateRangePicker
                   dateRange={dateRange}
                   setDateRange={(r) => { setActivePreset(-1); setDateRange(r); }}
                 />
              </div>
            </div>

            {/* Logout (US-017) */}
            <Button
              variant="ghost"
              size="sm"
              onClick={handleLogout}
              aria-label="Sair"
              className="h-9 gap-2 text-white/40 hover:text-white hover:bg-white/5 rounded-lg"
            >
              <LogOut className="h-4 w-4" />
              <span className="hidden sm:inline-block">Sair</span>
            </Button>
          </div>
        </header>

        {/* ═══ TABS ═══ */}
        <Tabs defaultValue="overview" className="space-y-8 relative z-10 border-none outline-none">
          <TabsList className="bg-transparent h-auto p-0 flex gap-6 overflow-x-auto border-b border-border/10 pb-0 w-full justify-start rounded-none custom-scrollbar">
            {TABS.map((t) => {
              const Icon = t.icon;
              return (
                <TabsTrigger key={t.value} value={t.value}
                  className="bg-transparent data-[state=active]:bg-transparent data-[state=active]:shadow-none data-[state=active]:text-white text-white/40 px-0 pb-4 pt-2 gap-2 rounded-none border-b-2 border-transparent data-[state=active]:border-emerald-400 text-sm font-semibold transition-colors whitespace-nowrap">
                  <Icon className="h-4 w-4" />{t.label}
                </TabsTrigger>
              );
            })}
