            <TabsContent value="users" className="mt-0 focus-visible:outline-none"><UsersBrowser dateRange={dateRange} darcyMode={darcyMode} siteFilter={siteFilter} /></TabsContent>
            <TabsContent value="conversations" className="mt-0 focus-visible:outline-none"><ConversationMetrics dateRange={dateRange} darcyMode={darcyMode} siteFilter={siteFilter} /></TabsContent>
            <TabsContent value="questions" className="mt-0 focus-visible:outline-none"><QuestionFrequencyMetrics dateRange={dateRange} /></TabsContent>
