import { useState } from "react";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Download, FileText, Sheet, Loader2 } from "lucide-react";
import { toast } from "sonner";
import { fetchInteractions, downloadCSV, openPrintableReport } from "@/lib/exportInteractions";

/**
 * Exporta TODAS as interações (telemetry_turns) do período selecionado (dateRange)
 * como Relatório imprimível (PDF) ou Planilha (CSV). Conteúdo redigido (LGPD).
 */
export function ExportButton({ dateRange }: { dateRange: { from: Date; to: Date } }) {
  const [loading, setLoading] = useState(false);

  const run = async (kind: "pdf" | "csv") => {
    if (loading) return;
    setLoading(true);
    const id = toast.loading("Reunindo as interações do período…");
    try {
      const rows = await fetchInteractions(dateRange.from, dateRange.to);
      if (rows.length === 0) {
        toast.error("Nenhuma interação no período selecionado.", { id });
        return;
      }
      if (kind === "csv") {
        downloadCSV(rows, dateRange.from, dateRange.to);
        toast.success(`${rows.length} interações exportadas (CSV).`, { id });
      } else {
        const ok = openPrintableReport(rows, dateRange.from, dateRange.to);
        if (ok) toast.success(`Relatório gerado (${rows.length} interações). Use Imprimir → Salvar como PDF.`, { id });
        else toast.error("O navegador bloqueou a janela do relatório. Permita pop-ups e tente de novo.", { id });
      }
    } catch (e: unknown) {
      toast.error("Falha ao exportar: " + (e instanceof Error ? e.message : String(e)), { id });
    } finally {
      setLoading(false);
    }
  };

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          variant="ghost"
          size="sm"
          disabled={loading}
          aria-label="Exportar interações do período"
          className="h-9 gap-2 text-white/60 hover:text-white hover:bg-white/5 rounded-lg"
        >
          {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Download className="h-4 w-4" />}
          <span className="hidden sm:inline-block">Exportar</span>
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="bg-[#121212] border-white/10 text-white backdrop-blur-xl rounded-xl shadow-2xl z-[100]">
        <DropdownMenuItem onClick={() => run("pdf")} className="gap-2 cursor-pointer text-xs focus:bg-white/10 focus:text-white rounded-lg mx-1 my-0.5">
          <FileText className="h-4 w-4 text-emerald-400" /> Relatório (PDF)
        </DropdownMenuItem>
        <DropdownMenuItem onClick={() => run("csv")} className="gap-2 cursor-pointer text-xs focus:bg-white/10 focus:text-white rounded-lg mx-1 my-0.5">
          <Sheet className="h-4 w-4 text-emerald-400" /> Planilha (CSV)
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

