// exportInteractions.ts — exporta as INTERAÇÕES (telemetry_turns) de um período
// como CSV (planilha) e como RELATÓRIO IMPRIMÍVEL (abre p/ imprimir → Salvar como PDF).
// Conteúdo REDIGIDO (PII mascarada/LGPD), idêntico ao resto do painel. Busca via
// dashboard-api paginando (maxLimit 500/recurso) e desduplicando por turn_id.

import { dashboardQuery } from "@/lib/dashboardApi";

export interface InteractionRow {
  turn_id: string;
  created_at: string;
  darcy_mode: string | null;
  verified_role: string | null;
  course_id: number | null;
  moodle_user_id: number | null;
  moodle_origin: string | null;
  model_used: string | null;
  total_tokens: number | null;
  cost_usd: number | null;
  latency_ms: number | null;
  quality_gate_passed: boolean | null;
  fallback_count: number | null;
  user_message_redacted: string | null;
  assistant_message_redacted: string | null;
}

const COLUMNS = [
  "turn_id", "created_at", "darcy_mode", "verified_role", "course_id", "moodle_user_id",
  "moodle_origin", "model_used", "total_tokens", "cost_usd", "latency_ms",
  "quality_gate_passed", "fallback_count", "user_message_redacted", "assistant_message_redacted",
];
const PAGE = 500;

// Busca TODAS as interações no intervalo [from, to] (paginação por created_at asc).
export async function fetchInteractions(from: Date, to: Date): Promise<InteractionRow[]> {
  const toIso = to.toISOString();
  const seen = new Set<string>();
  const all: InteractionRow[] = [];
  let cursor = from.toISOString();

  for (let i = 0; i < 400; i++) { // teto de segurança (~200k turnos)
    const batch = await dashboardQuery<InteractionRow>({
      resource: "telemetry_turns",
      columns: COLUMNS,
      filters: [
        { op: "gte", column: "created_at", value: cursor },
        { op: "lte", column: "created_at", value: toIso },
      ],
      order: { column: "created_at", ascending: true },
      limit: PAGE,
    });
    let added = 0;
    for (const r of batch) {
      if (r.turn_id && !seen.has(r.turn_id)) { seen.add(r.turn_id); all.push(r); added++; }
    }
    if (batch.length < PAGE) break;            // última página
    cursor = batch[batch.length - 1].created_at; // próxima a partir do último (gte → dedupe cobre a borda)
    if (added === 0) break;                    // anti-loop (página inteira já vista)
  }
  return all;
}

// ── CSV ──────────────────────────────────────────────────────────────────────
function csvEscape(v: unknown): string {
  const s = v === null || v === undefined ? "" : String(v);
  return /[",\n;]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}

export function buildCSV(rows: InteractionRow[]): string {
  const headers = [
    "data_hora", "modo", "papel", "curso_id", "usuario_moodle", "origem", "modelo",
    "tokens", "custo_usd", "latencia_ms", "gate_ok", "fallbacks", "pergunta", "resposta",
  ];
  const lines = [headers.join(";")];
  for (const r of rows) {
    lines.push([
      new Date(r.created_at).toLocaleString("pt-BR"),
      r.darcy_mode ?? "", r.verified_role ?? "", r.course_id ?? "", r.moodle_user_id ?? "",
      r.moodle_origin ?? "", r.model_used ?? "", r.total_tokens ?? "", r.cost_usd ?? "",
      r.latency_ms ?? "", r.quality_gate_passed ?? "", r.fallback_count ?? "",
      r.user_message_redacted ?? "", r.assistant_message_redacted ?? "",
    ].map(csvEscape).join(";"));
  }
  return lines.join("\n");
}

function fileStamp(d: Date): string { return d.toISOString().slice(0, 10); }

export function downloadCSV(rows: InteractionRow[], from: Date, to: Date): void {
  const csv = "﻿" + buildCSV(rows); // BOM p/ acentos abrirem certo no Excel
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `darcy-interacoes_${fileStamp(from)}_a_${fileStamp(to)}.csv`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

// ── Relatório imprimível (PDF via window.print) ───────────────────────────────
function htmlEscape(s: unknown): string {
  return String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

export function openPrintableReport(rows: InteractionRow[], from: Date, to: Date): boolean {
  const w = window.open("", "_blank");
  if (!w) return false; // popup bloqueado
  const fmt = (d: string) => new Date(d).toLocaleString("pt-BR");
  const period = `${from.toLocaleDateString("pt-BR")} — ${to.toLocaleDateString("pt-BR")}`;
  const blocks = rows.map((r, i) => `
    <article class="turn">
      <div class="meta">#${i + 1} · ${fmt(r.created_at)} · ${htmlEscape(r.darcy_mode || "-")} · ${htmlEscape(r.verified_role || "-")} · ${htmlEscape(r.moodle_origin || "-")} · ${htmlEscape(r.model_used || "-")}</div>
      <div class="q"><span class="lbl">Pergunta</span>${htmlEscape(r.user_message_redacted || "")}</div>
      <div class="a"><span class="lbl">Resposta</span>${htmlEscape(r.assistant_message_redacted || "")}</div>
    </article>`).join("");
  w.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8">
    <title>Darcy — Relatório de Interações (${period})</title>
    <style>
      *{box-sizing:border-box} body{font-family:-apple-system,Segoe UI,Roboto,Arial,sans-serif;color:#111;margin:32px;line-height:1.45}
      header{border-bottom:2px solid #10b981;padding-bottom:12px;margin-bottom:20px}
      h1{margin:0 0 4px;font-size:20px} .sub{color:#555;font-size:12px}
      .turn{border:1px solid #e5e7eb;border-radius:8px;padding:12px 14px;margin:0 0 12px;page-break-inside:avoid}
      .meta{color:#6b7280;font-size:11px;margin-bottom:8px;font-family:ui-monospace,SFMono-Regular,Menlo,monospace}
      .q,.a{white-space:pre-wrap;font-size:13px;margin-top:6px}
      .a{padding-left:10px;border-left:3px solid #10b981}
      .lbl{display:inline-block;font-weight:700;font-size:10px;text-transform:uppercase;letter-spacing:.05em;color:#10b981;margin-right:8px}
      @media print{ body{margin:12mm} .turn{break-inside:avoid} }
    </style></head><body>
    <header>
      <h1>Darcy — Relatório de Interações</h1>
      <div class="sub">Período: ${period} · Total: ${rows.length} interações · Gerado em ${new Date().toLocaleString("pt-BR")} · Dados pessoais mascarados (LGPD)</div>
    </header>
    ${blocks || "<p>Nenhuma interação no período.</p>"}
    <script>window.onload=function(){setTimeout(function(){window.print()},350)}</script>
    </body></html>`);
  w.document.close();
  return true;
}

